import time

def mint_scoped_token(resource: str, action: str, ttl_seconds: int = 300):
    # a real system signs this (e.g. STS, JWT); here we model the claims
    return {
        "resource": resource,       # only this bucket / table
        "action": action,           # only this verb, e.g. 'read'
        "expires_at": time.time() + ttl_seconds,
    }

token = mint_scoped_token("s3://reports/2026-q2", "read", ttl_seconds=120)
# even if this leaks, it can only read one prefix, and only for 2 minutes

MUTATING_ACTIONS = {"write", "delete", "update", "send", "pay"}

def check_action(action: str, caps: "ToolCaps") -> None:
    if action in MUTATING_ACTIONS and not caps.can_write:
        # writes are opt-in, never the default
        raise PermissionError(f"tool lacks write capability for '{action}'")

# reads sail through; a stray delete is blocked unless explicitly granted
check_action("read", read_reports)     # ok
check_action("delete", read_reports)   # PermissionError

def permissioned(tool_fn, caps, action, path_arg=None):
    def wrapped(**kwargs):
        check_action(action, caps)                 # capability gate
        if path_arg and path_arg in kwargs:
            kwargs[path_arg] = safe_path(kwargs[path_arg])  # allowlist gate
        return tool_fn(**kwargs)                    # only now run for real
    return wrapped

def _read_file(path): return open(path).read()
read_tool = permissioned(_read_file, read_reports, "read", path_arg="path")
# every call is checked; the raw _read_file is never exposed to the agent

