from dataclasses import dataclass

@dataclass
class ToolCaps:
    can_read: bool
    can_write: bool
    root: str

MUTATING = {"write", "delete", "update"}

def authorize(action: str, caps: ToolCaps) -> str:
    if action in MUTATING and not caps.can_write:
        return f"DENIED: '{action}' needs write capability"
    if action == "read" and not caps.can_read:
        return f"DENIED: '{action}' needs read capability"
    return f"ALLOWED: {action}"

# the summarizer only ever needs to read one folder
summarizer = ToolCaps(can_read=True, can_write=False, root="/data/reports")

print(authorize("read", summarizer))
print(authorize("delete", summarizer))  # blocked by least privilege

