from dataclasses import dataclass

@dataclass
class ToolCaps:
    can_read: bool
    can_write: bool
    root: str

def safe_path(user_path: str, root: str) -> str:
    allowed = os.path.realpath(root)
    resolved = os.path.realpath(user_path)   # collapse '..' and symlinks first
    if resolved != allowed and not resolved.startswith(allowed + os.sep):
        raise PermissionError(f"path escapes sandbox: {user_path}")
    return resolved

def permissioned(tool_fn, caps: ToolCaps, action: str, path_arg=None):
    def wrapped(**kwargs):
        if action in {"write", "delete"} and not caps.can_write:
            raise PermissionError(f"tool lacks write for '{action}'")
        if path_arg and path_arg in kwargs:
            kwargs[path_arg] = safe_path(kwargs[path_arg], caps.root)
        return tool_fn(**kwargs)
    return wrapped

caps = ToolCaps(can_read=True, can_write=False, root="/data/reports")
def _read(path): return f"<contents of {path}>"
read_tool = permissioned(_read, caps, "read", path_arg="path")

