from dataclasses import dataclass, field
from urllib.parse import urlparse

MUTATING = {"write", "delete", "send"}

@dataclass
class ToolCaps:
    can_write: bool = False
    allowed_domains: set = field(default_factory=set)

def guard_call(tool_fn, caps: ToolCaps, action: str, url: str = None):
    # 1) capability gate: mutating actions require write
    if action in MUTATING and not caps.can_write:
        raise PermissionError(f"tool lacks write capability for '{action}'")
    # 2) domain allowlist: match the parsed host exactly, never a substring
    if url is not None:
        host = urlparse(url).hostname
        if host not in caps.allowed_domains:
            raise PermissionError(f"domain not allowlisted: {host}")
    # 3) only now invoke the real tool
    return tool_fn(url=url) if url is not None else tool_fn()

