import os

MUTATING = {"write", "delete", "update"}

def safe_path(user_path: str, root: str) -> str:
    allowed = os.path.realpath(root)
    resolved = os.path.realpath(user_path)   # collapse '..' and symlinks FIRST
    if resolved != allowed and not resolved.startswith(allowed + os.sep):
        raise PermissionError(f"path escapes sandbox: {user_path}")
    return resolved

def make_permissioned(tool_fn, *, action, can_write=False, root=None, path_arg=None):
    def wrapped(**kwargs):
        if action in MUTATING and not can_write:       # read-only by default
            raise PermissionError(f"tool lacks write for '{action}'")
        if path_arg and path_arg in kwargs and root:    # allowlist the path
            kwargs[path_arg] = safe_path(kwargs[path_arg], root)
        return tool_fn(**kwargs)                         # only now run for real
    return wrapped

if __name__ == "__main__":
    def _read(path): return f"read {path}"
    read_tool = make_permissioned(_read, action="read", root="/data", path_arg="path")
    print(read_tool(path="/data/report.txt"))
    try:
        read_tool(path="/data/../etc/passwd")
    except PermissionError as e:
        print("blocked:", e)
